{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "There is limited evidence in peer-reviewed literature on modelling for malaria optimization in limited resource settings. The country focus of the modelling studies included in the review were not representative of the burden of malaria in sub-Saharan Africa. ... The limited number of modelling analyses for malaria control optimization specific to countries within Africa and Asia is as a consequence of the lack or inaccessibility of country-specific epidemiologic and cost data at the national and subnational levels. This data gap limits future studies within the respective countries, limits the build-up of a critical mass of modellers within these countries, and makes it challenging for policymakers to make an evidence-based informed case to potential donors for future funding.",
      "reason": "Text explicitly describes the current state of knowledge (limited evidence, geographic gaps) and important uncertainties/data gaps limiting modelling studies and policy use."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Background Despite advances made in curbing the global malaria burden since the 2000s, progress has stalled, in part due to a plateauing of the financing available to implement needed interventions. In 2020, approximately 3.3 billion USD was invested globally for malaria interventions, falling short of the targeted 6.8 billion USD set by the GTS, increasing the financial gap between desirable and actual investment. Models for malaria control optimization are used to disentangle the most efficient interventions or packages of interventions for inherently constrained budgets. This systematic review aimed to identify and characterise models for malaria control optimization for resource allocation in limited resource settings and assess their strengths and limitations.",
      "reason": "Abstract states the financing shortfall and explicitly explains the need and purpose of the review (to identify and characterise optimisation models for resource allocation in limited-resource settings)."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No text in the provided evidence explains whether similar systematic reviews exist, nor cites or contrasts previous reviews or justifies the current review as an update/replication."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "Models for malaria control optimization are used to disentangle the most efficient interventions or packages of interventions for inherently constrained budgets.",
      "reason": "The review focuses on optimisation models for resource allocation rather than evaluating intervention effects; thus describing an intervention's mechanism of action is not applicable based on the manuscript's stated aim."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_10",
      "quote": "All studies investigated WHO-recommended interventions for control or elimination targets (Table 2), such as insecticide-treated nets [10, 11, 16-18, 25, 28, 29, 33-38], seasonal malaria chemoprevention [16, 18, 25, 28, 33, 37], intermittent preventive treatment [16, 25, 28, 37, 38], indoor residual spraying [16-18, 28, 29, 32-38], mass drug administration [16, 18, 29], and diagnosis and treatment through community health workers or health facilities [10, 11, 25, 28, 29, 32, 35-38].",
      "reason": "The review summarises modelling studies and interventions considered but does not present or require a logic model for hypothesised causal pathways; given the review's modelling/optimization focus, inclusion of a logic model for complex interventions is not applicable in the provided evidence."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "'The research question for this review was ' Are there English-language publications in peer-reviewed scientific journals describing how models have been used to allocate resources for malaria interventions in limited resource settings?' The main aim of this review was to identify and characterize models for malaria control optimization for resource allocation in malaria control and elimination settings and to identify their strengths and limitations.'",
      "reason": "The document explicitly states a clear research question and the main aim/objectives of the review, satisfying the requirement for an explicit statement of objectives/questions."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review addresses identification and characterization of optimisation models rather than effects of interventions; no planned intervention-effect comparisons using PICO or similar are relevant to this review's stated research question."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Each record in the search were included if they met all of the following criteria: (1) Were scientific peer-reviewed journals written in English; (2) Were published before 30th June 2024; (3) Studies were included irrespective of the targeted geographical regions; (4) Studies were included irrespective of the population subgroups; (5) Studies containing an optimization model (mathematical or statistical); (6) All studies with human Plasmodium species; (7) Studies with two or more interventions; (8) Cost data were used in combination with the model outputs; (9) Outcomes/health benefits were clearly stated and/or measured.",
      "reason": "The manuscript lists specific study characteristics used to determine eligibility, including publication type/language, date, geographic and population scope, model type, pathogen (human Plasmodium), number of interventions, requirement for cost data, and outcomes."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "(1) Were scientific peer-reviewed journals written in English; (2) Were published before 30th June 2024;",
      "reason": "Eligibility criteria for report characteristics are specified explicitly (language = English; dissemination/publication date cutoff = before 30 June 2024). Exclusions of certain report types are also reported elsewhere (e.g. text_9)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported; the evidence does not address this distinction."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "All extracted data were double checked for errors by a second independent reviewer (SP) and discrepancies in entries were settled by appropriate discussion among both reviewers (RN and SP). A narrative synthesis of the study characteristics was performed.",
      "reason": "The review reports performing a narrative synthesis and presents grouped study characteristics (see Table 2 / table_1) such as region, interventions, model types and population. However, it does not explicitly specify the groups used in each synthesis and link those groups to the comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No rationale is provided for notable restrictions on study eligibility (for example language or publication-type restrictions are stated but not justified in the provided evidence)."
    }
  ],
  "confidence": 80
}

